 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [[background] * w for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            if len(cells) < 4:
                continue
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            area = (r1 - r0 + 1) * (c1 - c0 + 1)
            # Keep dense, rectangle-like objects and repair isolated marker
            # interruptions; discard sparse specks and other noise.
            if len(cells) / area < 0.70:
                continue
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    out[y][x] = color
    return out
